import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"💡 05 · 设计 / 售前 / FDE（客户成功）","description":"","frontmatter":{},"headers":[],"relativePath":"07-开发岗-前后端与全栈/05-设计售前FDE.md","filePath":"07-开发岗-前后端与全栈/05-设计售前FDE.md","lastUpdated":1786806808000}'),o={name:"07-开发岗-前后端与全栈/05-设计售前FDE.md"};function i(n,e,s,d,h,p){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="💡-05-·-设计-售前-fde-客户成功" tabindex="-1">💡 05 · 设计 / 售前 / FDE（客户成功） <a class="header-anchor" href="#💡-05-·-设计-售前-fde-客户成功" aria-label="Permalink to &quot;💡 05 · 设计 / 售前 / FDE（客户成功）&quot;">​</a></h1><blockquote><p>AI 落地不止技术——还需要把技术「翻译」成客户价值。这些岗位对「懂 AI 又懂人」的人需求旺盛。</p></blockquote><hr><h2 id="一、产品设计-ux-ai-产品" tabindex="-1">一、产品设计 / UX（AI 产品） <a class="header-anchor" href="#一、产品设计-ux-ai-产品" aria-label="Permalink to &quot;一、产品设计 / UX（AI 产品）&quot;">​</a></h2><ul><li><strong>AI 交互设计</strong>：如何呈现不确定性（模型可能错）、何时让用户确认、如何展示「思考过程」。</li><li><strong>防幻觉体验</strong>：给出处、可溯源、标注「AI 生成」。</li><li><strong>人机协作</strong>：把 AI 当协作者而非全自动，设计人工介入点。</li><li>核心能力：用户研究、原型、数据驱动迭代。</li></ul><h2 id="二、售前-解决方案-pre-sales" tabindex="-1">二、售前 / 解决方案（Pre-sales） <a class="header-anchor" href="#二、售前-解决方案-pre-sales" aria-label="Permalink to &quot;二、售前 / 解决方案（Pre-sales）&quot;">​</a></h2><ul><li>把 AI 能力映射到客户业务痛点（降本/增效/创新）。</li><li>做 POC（概念验证）、写方案、技术答疑、竞品对比。</li><li>需「半技术 + 半商业」：懂模型边界，也懂 ROI。</li></ul><h2 id="三、fde-field-deployment-engineer-现场交付" tabindex="-1">三、FDE（Field Deployment Engineer / 现场交付） <a class="header-anchor" href="#三、fde-field-deployment-engineer-现场交付" aria-label="Permalink to &quot;三、FDE（Field Deployment Engineer / 现场交付）&quot;">​</a></h2><ul><li>把 AI 产品部署到客户环境（私有化、信创、离线）。</li><li>做适配、调优、培训、问题排查。</li><li>需扎实的工程 + 沟通能力，是「离钱近」的技术岗。</li></ul><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：AI 产品设计最该注意什么？</strong></p><blockquote><p>管理用户对「确定性」的预期——AI 会错，要在交互上给降级/确认/溯源，避免用户盲目信任导致事故。</p></blockquote><p><strong>Q2：售前怎么讲清模型能力边界？</strong></p><blockquote><p>用「能做什么/不能做什么/在什么条件下效果好」三句话，配 POC 演示；过度承诺是售后的坑，坦诚边界反而建立信任。</p></blockquote><hr><p>➡️ 返回：<a href="./README">07-开发岗-前后端与全栈 README</a> ｜ 进入：<a href="./../08-AI应用开发/README">08-AI应用开发</a></p>',16)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
